function parseTimeRange(v){let s=String(v??'').trim().replace(/[–—]/g,'-').replace(/\./g,':');let m=s.match(/(\d{1,2})\s*[:h]\s*(\d{2})\s*-\s*(\d{1,2})\s*[:h]\s*(\d{2})/i);return m?[`${pad(m[1])}:${m[2]}`,`${pad(m[3])}:${m[4]}`]:['','']}
