function escHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function levenshtein(a,b){a=String(a);b=String(b);let v0=Array(b.length+1).fill(0).map((_,i)=>i),v1=Array(b.length+1);for(let i=0;i<a.length;i++){v1[0]=i+1;for(let j=0;j<b.length;j++){let cost=a[i]===b[j]?0:1;v1[j+1]=Math.min(v1[j]+1,v0[j+1]+1,v0[j]+cost)}[v0,v1]=[v1,v0]}return v0[b.length]}
function cleanOcrName(raw){return String(raw||'').replace(/[|_~`^]+/g,' ').replace(/[“”‘’]/g,'').replace(/[^A-Za-zÀ-ỹĐđ\s.-]/g,' ').replace(/\s+/g,' ').trim()}
