function bestNameFromList(raw,list){let text=cleanOcrName(raw);if(!text)return {value:'',uncertain:true,score:1,raw:text};let n=normText(text);if(n.includes('nghi'))return {value:text,uncertain:false,score:0,raw:text};let best={name:text,score:1};for(let name of (list&&list.length?list:KNOWN_PEOPLE)){let q=normText(name),cand=scoreName(n,q);if(cand<best.score)best={name,score:cand};for(let w of nameWindows(text,Math.max(2,q.split(' ').length-1),q.split(' ').length+1)){let sc=scoreName(w,q);if(sc<best.score)best={name,score:sc}}}return best.score<=0.30?{value:best.name,uncertain:best.score>0.15,score:best.score,raw:text}:{value:text,uncertain:true,score:best.score,raw:text}}
