function ocrLineGroups(words,height){let a=(words||[]).filter(w=>w&&w.text&&w.bbox).map(w=>({...w,cx:(w.bbox.x0+w.bbox.x1)/2,cy:(w.bbox.y0+w.bbox.y1)/2})).sort((x,y)=>x.cy-y.cy||x.cx-y.cx),groups=[],tol=Math.max(8,height*.009);a.forEach(w=>{let g=groups.findLast?groups.findLast(g=>Math.abs(g.cy-w.cy)<=tol):[...groups].reverse().find(g=>Math.abs(g.cy-w.cy)<=tol);if(!g){g={cy:w.cy,words:[]};groups.push(g)}g.words.push(w);g.cy=g.words.reduce((s,x)=>s+x.cy,0)/g.words.length});groups.forEach(g=>{g.words.sort((a,b)=>a.cx-b.cx);g.text=g.words.map(w=>w.text).join(' ').replace(/\s+/g,' ').trim()});return groups.sort((a,b)=>a.cy-b.cy)}
function dateInOcrText(text,monthKey){let cleaned=String(text||'').replace(/[Oo]/g,'0').replace(/[Il]/g,'1');let matches=[...cleaned.matchAll(/(\d{1,2})\s*[\/\-.]\s*(\d{1,2})\s*[\/\-.]\s*(\d{2,4})/g)];if(matches.length!==1)return'';let m=matches[0],y=Number(m[3]);if(y<100)y+=2000;let d=`${y}-${pad(m[2])}-${pad(m[1])}`;return d.startsWith(monthKey)?d:''}
function wordsInBand(words,x0,x1,y0,y1){return (words||[]).filter(w=>{let cx=(w.bbox.x0+w.bbox.x1)/2,cy=(w.bbox.y0+w.bbox.y1)/2;return cx>=x0&&cx<x1&&cy>=y0&&cy<y1})}
