 return `<w:p><w:pPr>${keep}${opt.align?'<w:jc w:val="'+opt.align+'"/>':''}<w:spacing w:before="0" w:after="0" w:line="240" w:lineRule="auto"/></w:pPr>${runs}</w:p>`
