async function adminLogin(){let pin=$('#adminPin').value.trim();$('#adminError').textContent='';if(!pin){$('#adminError').textContent='Anh nhập mã Admin.';return}let hash=await sha256Text(pin);if(hash!==ADMIN_PIN_HASH){$('#adminError').textContent='Mã Admin chưa đúng.';return}IS_ADMIN=true;sessionStorage.setItem('dutyAdminUnlocked','1');applyAdminUI();syncAdminModal()}
function adminLogout(){IS_ADMIN=false;sessionStorage.removeItem('dutyAdminUnlocked');applyAdminUI();syncAdminModal()}
$('#settingsBtn').onclick=openSettings;$('#closeSettings').onclick=closeSettings;$('#adminLoginBtn').onclick=adminLogin;$('#adminPin').onkeydown=e=>{if(e.key==='Enter')adminLogin()};$('#adminLogoutBtn').onclick=adminLogout;$('#openSourceAdmin').onclick=()=>{closeSettings();show('source')};$('#openGenerateAdmin').onclick=()=>{closeSettings();show('generate')};settingsModal.addEventListener('click',e=>{if(e.target===settingsModal)closeSettings()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&settingsModal.classList.contains('open'))closeSettings()});
$('#leaderSelect').onchange=e=>chooseRolePerson('leader',e.target.value);$('#managerSelect').onchange=e=>chooseRolePerson('manager',e.target.value);$('#personSelect').onchange=()=>{PERSON_MODE='all';renderQuick();renderMine();$('#statPerson').value=$('#personSelect').value;renderStats()};$('#myBtn').onclick=()=>show('mine');$('#refreshBtn').onclick=tryRefresh;$('#monthViewSelect').onchange=renderMonth;$('#generateBtn').onclick=generateMonth;$('#wordBtn').onclick=downloadWord;$('#csvBtn').onclick=downloadCSV;$('#copyBtn').onclick=copyGenerated;$('#statPerson').onchange=renderStats;$('#statMonth').onchange=renderStats;$('#findBtn').onclick=findPerson;$('#findInput').onkeydown=e=>{if(e.key==='Enter')findPerson()};$('#sourceFile').onchange=e=>{let fs=e.target.files;if(fs&&fs.length)readSourceFiles(fs)};$('#readSourceBtn').onclick=readSourcePaste;$('#saveSourceBtn').onclick=saveSourcePreview;$('#clearPreviewBtn').onclick=clearSourcePreview;$('#sourceMonth').onchange=()=>{let k=$('#sourceMonth').value;if(SOURCE_MONTHS[k])viewSourceMonth(k);else{SOURCE_PREVIEW=[];SOURCE_PREVIEW_MONTH='';renderSourcePreview();renderSourceStats(k,[])}};let sourceDrop=$('#sourceDrop');['dragenter','dragover'].forEach(ev=>sourceDrop.addEventListener(ev,e=>{e.preventDefault();sourceDrop.classList.add('drag')}));['dragleave','drop'].forEach(ev=>sourceDrop.addEventListener(ev,e=>{e.preventDefault();sourceDrop.classList.remove('drag')}));sourceDrop.addEventListener('drop',e=>{let fs=e.dataTransfer.files;if(fs&&fs.length){try{$('#sourceFile').files=fs}catch{}readSourceFiles(fs)}});boot();

$('#mineFilters').addEventListener('click',e=>{let b=e.target.closest('[data-filter]');if(!b)return;PERSON_MODE='all';MINE_FILTER=b.dataset.filter;document.querySelectorAll('#mineFilters .filterchip').forEach(x=>x.classList.toggle('active',x===b));renderMine();});
